// =============================================================================
// ENEMY AI SYSTEM
// =============================================================================

import { TILE, ENEMY_STATE, ENEMY_STATS, isSolidTile } from './gameData';
import { CONFIG, canvasDims } from './config';
import { getTile, getTileHeight, isWalkable, isDoorPassable } from './levelHelpers';
import { playSound } from './audio';
import { attackWarnings } from './effects';

export const hasLineOfSight = (map, x1, y1, x2, y2) => {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const dist = Math.sqrt(dx * dx + dy * dy);
  if (dist < 0.01) return true;

  const steps = Math.ceil(dist / 0.3);
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const sx = x1 + dx * t;
    const sy = y1 + dy * t;
    const tile = getTile(map, sx, sy);
    if (isSolidTile(tile)) {
      // Open doors don't block line of sight
      if (tile === TILE.DOOR && isDoorPassable(Math.floor(sx), Math.floor(sy))) {
        continue;
      }
      return false;
    }
  }
  return true;
};

export const updateEnemies = (enemies, map, playerX, playerY, onPlayerDamage, onEnemyKilled, dt = 1, playerAngle = 0, heightMap = null) => {
  for (let i = 0; i < enemies.length; i++) {
    const enemy = enemies[i];
    if (enemy.state === ENEMY_STATE.DEAD) continue;

    const stats = ENEMY_STATS[enemy.type];
    const dx = playerX - enemy.x;
    const dy = playerY - enemy.y;
    const distToPlayer = Math.sqrt(dx * dx + dy * dy);
    const angleToPlayer = Math.atan2(dy, dx);

    if (enemy.attackTimer > 0) enemy.attackTimer -= dt;
    if (enemy.hurtTimer > 0) enemy.hurtTimer -= dt;
    if (enemy.alertTimer > 0) enemy.alertTimer -= dt;
    if (enemy.projectileTimer > 0) {
      enemy.projectileTimer -= dt;
      if (enemy.projectileTimer <= 0) {
        if (hasLineOfSight(map, enemy.x, enemy.y, playerX, playerY)) {
          onPlayerDamage(stats.damage);
        }
      }
    }

    switch (enemy.state) {
      case ENEMY_STATE.IDLE: {
        if (enemy.thinkTimer <= 0) {
          enemy.thinkTimer = 30;
          if (distToPlayer <= stats.sightRange && hasLineOfSight(map, enemy.x, enemy.y, playerX, playerY)) {
            enemy.state = ENEMY_STATE.ALERT;
            enemy.alertTimer = 30;
            enemy.angle = angleToPlayer;
          }
        }
        enemy.thinkTimer -= dt;
        break;
      }

      case ENEMY_STATE.ALERT: {
        enemy.angle = angleToPlayer;
        if (enemy.alertTimer <= 0) {
          enemy.state = ENEMY_STATE.CHASE;
        }
        break;
      }

      case ENEMY_STATE.CHASE: {
        if (distToPlayer > stats.sightRange * 1.5) {
          if (!hasLineOfSight(map, enemy.x, enemy.y, playerX, playerY)) {
            enemy.state = ENEMY_STATE.IDLE;
            enemy.thinkTimer = 60;
            break;
          }
        }

        if (distToPlayer <= stats.attackRange) {
          enemy.state = ENEMY_STATE.ATTACK;
          break;
        }

        enemy.angle = angleToPlayer;
        const enemySpeed = stats.speed * dt;
        const moveX = Math.cos(angleToPlayer) * enemySpeed;
        const moveY = Math.sin(angleToPlayer) * enemySpeed;
        const ENEMY_RADIUS = 0.2;
        const eFloorH = heightMap ? getTileHeight(map, heightMap, enemy.x, enemy.y).floorH : 0;
        const newX = enemy.x + moveX;
        const newY = enemy.y + moveY;

        if (isWalkable(map, newX, enemy.y, ENEMY_RADIUS, heightMap, eFloorH)) {
          enemy.x = newX;
        } else {
          const slideAngle = angleToPlayer + (Math.random() > 0.5 ? Math.PI / 2 : -Math.PI / 2);
          const slideX = enemy.x + Math.cos(slideAngle) * enemySpeed;
          if (isWalkable(map, slideX, enemy.y, ENEMY_RADIUS, heightMap, eFloorH)) {
            enemy.x = slideX;
          }
        }
        if (isWalkable(map, enemy.x, newY, ENEMY_RADIUS, heightMap, eFloorH)) {
          enemy.y = newY;
        } else {
          const slideAngle = angleToPlayer + (Math.random() > 0.5 ? Math.PI / 2 : -Math.PI / 2);
          const slideY = enemy.y + Math.sin(slideAngle) * enemySpeed;
          if (isWalkable(map, enemy.x, slideY, ENEMY_RADIUS, heightMap, eFloorH)) {
            enemy.y = slideY;
          }
        }
        break;
      }

      case ENEMY_STATE.ATTACK: {
        enemy.angle = angleToPlayer;

        if (distToPlayer > stats.attackRange * 1.3) {
          enemy.state = ENEMY_STATE.CHASE;
          attackWarnings.remove(enemy.id);
          break;
        }

        if (enemy.attackTimer <= 0) {
          enemy.attackTimer = stats.attackCooldown;

          let relativeAngle = angleToPlayer - playerAngle + Math.PI;
          while (relativeAngle > Math.PI) relativeAngle -= 2 * Math.PI;
          while (relativeAngle < -Math.PI) relativeAngle += 2 * Math.PI;
          const screenX = (relativeAngle / CONFIG.FOV_RADIANS + 0.5) * canvasDims.width;
          const screenY = canvasDims.halfHeight;

          attackWarnings.add(enemy.id, screenX, screenY, stats.attackType);

          if (stats.attackType === 'melee') {
            if (distToPlayer <= stats.attackRange * 1.3) {
              onPlayerDamage(stats.damage);
            }
          } else if (stats.attackType === 'ranged') {
            enemy.projectileTimer = stats.projectileDelay || 20;
          }
        }
        break;
      }

      case ENEMY_STATE.HURT: {
        if (enemy.hurtTimer <= 0) {
          enemy.state = ENEMY_STATE.CHASE;
        }
        break;
      }

      default:
        break;
    }
  }
};

export const damageEnemy = (enemy, damage, onEnemyKilled) => {
  if (enemy.state === ENEMY_STATE.DEAD) return;

  enemy.health -= damage;

  if (enemy.health <= 0) {
    enemy.health = 0;
    enemy.state = ENEMY_STATE.DEAD;
    enemy.alive = false;
    enemy.deathTimer = 60;
    playSound('enemyDeath', 0.45);
    if (onEnemyKilled) onEnemyKilled(enemy);
  } else {
    enemy.state = ENEMY_STATE.HURT;
    enemy.hurtTimer = 15;
    playSound('enemyHurt', 0.35);
  }
};

sources.levelHelpers.js:
// =============================================================================
// LEVEL HELPER FUNCTIONS
// =============================================================================

import { TILE, isSolidTile, isWallTile } from './gameData';
import { CONFIG } from './config';

// ---------------------------------------------------------------------------
// Door animation state
// ---------------------------------------------------------------------------
const DOOR_SPEED = 0.035;
const DOOR_STAY_OPEN = 240; // frames (~4 seconds at 60fps)
const DOOR_PASSABLE_AT = 0.7;
const DOOR_RAY_PASS_AT = 0.9;

// Map<string, { offset: number, state: string, autoCloseTimer: number }>
let doorStates = new Map();

const doorKey = (x, y) => `${x},${y}`;

export const initDoorStates = (map) => {
  doorStates = new Map();
  for (let y = 0; y < map.length; y++) {
    for (let x = 0; x < map[y].length; x++) {
      if (map[y][x] === TILE.DOOR) {
        doorStates.set(doorKey(x, y), { offset: 0, state: 'closed', autoCloseTimer: 0 });
      }
    }
  }
};

export const resetDoorStates = () => {
  doorStates = new Map();
};

export const getDoorOffset = (x, y) => {
  const ds = doorStates.get(doorKey(x, y));
  return ds ? ds.offset : 0;
};

export const isDoorPassable = (x, y) => {
  const ds = doorStates.get(doorKey(x, y));
  return ds ? ds.offset >= DOOR_PASSABLE_AT : false;
};

export const isDoorOpenForRay = (x, y) => {
  const ds = doorStates.get(doorKey(x, y));
  return ds ? ds.offset >= DOOR_RAY_PASS_AT : false;
};

export const updateDoorStates = (dt, playerX, playerY) => {
  for (const [key, ds] of doorStates) {
    switch (ds.state) {
      case 'opening':
        ds.offset = Math.min(1, ds.offset + DOOR_SPEED * dt);
        if (ds.offset >= 1) {
          ds.offset = 1;
          ds.state = 'open';
          ds.autoCloseTimer = DOOR_STAY_OPEN;
        }
        break;
      case 'open':
        ds.autoCloseTimer -= dt;
        if (ds.autoCloseTimer <= 0) {
          ds.state = 'closing';
        }
        break;
      case 'closing': {
        // Safety: if player is inside this door tile, reopen
        const [kx, ky] = key.split(',').map(Number);
        const px = Math.floor(playerX);
        const py = Math.floor(playerY);
        if (px === kx && py === ky) {
          ds.state = 'opening';
          break;
        }
        ds.offset = Math.max(0, ds.offset - DOOR_SPEED * dt);
        if (ds.offset <= 0) {
          ds.offset = 0;
          ds.state = 'closed';
        }
        break;
      }
    }
  }
};

export const tryToggleDoor = (map, px, py, angle) => {
  for (let dist = 0.5; dist <= 1.5; dist += 0.5) {
    const checkX = Math.floor(px + Math.cos(angle) * dist);
    const checkY = Math.floor(py + Math.sin(angle) * dist);
    const dims = getMapDimensions(map);
    if (checkX >= 0 && checkX < dims.width && checkY >= 0 && checkY < dims.height) {
      if (map[checkY][checkX] === TILE.DOOR) {
        const ds = doorStates.get(doorKey(checkX, checkY));
        if (!ds) continue;
        if (ds.state === 'closed' || ds.state === 'closing') {
          ds.state = 'opening';
          return 'open';
        } else if (ds.state === 'open' || ds.state === 'opening') {
          ds.state = 'closing';
          return 'close';
        }
      }
    }
  }
  return null;
};

export const getFacingDoorState = (map, px, py, angle) => {
  for (let dist = 0.5; dist <= 1.5; dist += 0.5) {
    const checkX = Math.floor(px + Math.cos(angle) * dist);
    const checkY = Math.floor(py + Math.sin(angle) * dist);
    const dims = getMapDimensions(map);
    if (checkX >= 0 && checkX < dims.width && checkY >= 0 && checkY < dims.height) {
      if (map[checkY][checkX] === TILE.DOOR) {
        const ds = doorStates.get(doorKey(checkX, checkY));
        if (!ds) continue;
        return ds.state;
      }
    }
  }
  return null;
};

export const getTile = (map, x, y) => {
  const mapX = Math.floor(x);
  const mapY = Math.floor(y);
  if (mapY < 0 || mapY >= map.length || mapX < 0 || mapX >= map[0].length) {
    return TILE.WALL_STONE;
  }
  return map[mapY][mapX];
};

export const getMapDimensions = (map) => ({
  width: map[0].length,
  height: map.length,
});

export const findTilePositions = (map, tileType) => {
  const positions = [];
  for (let y = 0; y < map.length; y++) {
    for (let x = 0; x < map[y].length; x++) {
      if (map[y][x] === tileType) {
        positions.push({ x: x + 0.5, y: y + 0.5 });
      }
    }
  }
  return positions;
};

// ---------------------------------------------------------------------------
// Height system
// ---------------------------------------------------------------------------

/**
 * Get the floor and ceiling height for a tile.
 * heightMap is an optional parallel array: heightMap[y][x] = [floorH, ceilH] or null.
 * Solid wall tiles always return floorH=0, ceilH=1 (full occlusion).
 * Out-of-bounds returns full solid.
 */
export const getTileHeight = (map, heightMap, x, y) => {
  const mapX = Math.floor(x);
  const mapY = Math.floor(y);

  if (mapY < 0 || mapY >= map.length || mapX < 0 || mapX >= map[0].length) {
    return { floorH: 0, ceilH: 1, type: TILE.WALL_STONE, solid: true };
  }

  const type = map[mapY][mapX];

  // Full solid walls are always floor-to-ceiling
  if (isSolidTile(type)) {
    return { floorH: 0, ceilH: 1, type, solid: true };
  }

  // Check heightMap for custom heights
  if (heightMap && heightMap[mapY] && heightMap[mapY][mapX]) {
    const [floorH, ceilH] = heightMap[mapY][mapX];
    return { floorH, ceilH, type, solid: false };
  }

  // Default: open space, floor at 0, ceiling at 1
  return { floorH: 0, ceilH: 1, type, solid: false };
};

/**
 * Height-aware walkability check.
 * currentFloorH = the floor height the entity is currently standing on.
 * Corners check for solid walls only. Height checks use the center position
 * to prevent corner-clipping at height transitions from blocking movement.
 */
export const isWalkable = (map, x, y, radius = 0.2, heightMap = null, currentFloorH = 0) => {
  const corners = [
    { x: x - radius, y: y - radius },
    { x: x + radius, y: y - radius },
    { x: x - radius, y: y + radius },
    { x: x + radius, y: y + radius },
  ];

  for (const corner of corners) {
    const tile = getTile(map, corner.x, corner.y);
    if (isSolidTile(tile)) {
      // Doors that are open enough are passable
      if (tile === TILE.DOOR) {
        const mx = Math.floor(corner.x);
        const my = Math.floor(corner.y);
        if (isDoorPassable(mx, my)) continue;
      }
      return false;
    }
  }

  // Height checks use center position only
  if (heightMap) {
    const h = getTileHeight(map, heightMap, x, y);
    // Step-up check: can't climb walls too high
    if (h.floorH - currentFloorH > CONFIG.MAX_STEP_HEIGHT) {
      return false;
    }
    // Clearance check: need enough headroom
    const standH = Math.max(h.floorH, currentFloorH);
    if (h.ceilH - standH < CONFIG.MIN_CLEARANCE) {
      return false;
    }
  }

  return true;
};

