          onMouseLeave={e => e.target.style.backgroundColor = '#60a5fa'}
        >
          Got it! (Space)
        </button>

        <p style={{
          textAlign: 'center',
          marginTop: '15px',
          fontSize: '13px',
          color: '#94a3b8'
        }}>
          Auto-starting in {timeLeft} seconds...
        </p>
      </div>
    </div>
  );
};

export default InstructionOverlay;

