// Input manager for keyboard controls

export class InputManager {
  constructor() {
    this.keys = {};
    this.enabled = true;
    this.handleKeyDown = this.handleKeyDown.bind(this);
    this.handleKeyUp = this.handleKeyUp.bind(this);
  }

  init() {
    window.addEventListener('keydown', this.handleKeyDown);
    window.addEventListener('keyup', this.handleKeyUp);
  }

  destroy() {
    window.removeEventListener('keydown', this.handleKeyDown);
    window.removeEventListener('keyup', this.handleKeyUp);
  }

  handleKeyDown(e) {
    if (!this.enabled) return;

    const key = e.key.toLowerCase();
    this.keys[key] = true;

    // Prevent arrow key scrolling
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) {
      e.preventDefault();
    }
  }

  handleKeyUp(e) {
    const key = e.key.toLowerCase();
    this.keys[key] = false;
  }

  isKeyPressed(key) {
    return this.enabled && this.keys[key.toLowerCase()];
  }

  isAnyKeyPressed(keys) {
    return keys.some(key => this.isKeyPressed(key));
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (!enabled) {
      this.keys = {};
    }
  }

  reset() {
    this.keys = {};
  }
}

sources.utils/vaderImage.js:
// Character image loader - loads canvas images using direct URLs
export const loadCharacterImage = (imageUrl) => {
  return new Promise((resolve) => {
    if (!imageUrl) {
      resolve(null);
      return;
    }

    const img = new Image();
    img.crossOrigin = 'anonymous';

    img.onload = () => {
      console.log('Canvas character image loaded successfully');
      resolve(img);
    };

    img.onerror = (e) => {
      console.error('Failed to load canvas character image:', e);
      resolve(null);
    };

    img.src = imageUrl;
  });
};

// Load all character images
export const loadAllCharacterImages = async (characters) => {
  const imagePromises = characters.map(char => 
    loadCharacterImage(char.imageUrl).then(img => ({ id: char.id, image: img }))
  );

  const results = await Promise.all(imagePromises);
  const imageMap = {};
  results.forEach(result => {
    if (result.image) {
      imageMap[result.id] = result.image;
    }
  });

  return imageMap;
};

